    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    out = [[0] * w for _ in range(h)]

    # Tiles: 2x2 squares, and L triominoes colored by their missing corner.
    tiles = []
    for r in range(h - 1):
        for c in range(w - 1):
            box = {(r,c), (r,c+1), (r+1,c), (r+1,c+1)}
            tiles.append((box, 1, 0))
            for missing, color in [((r,c), 2), ((r,c+1), 3),
                                   ((r+1,c), 4), ((r+1,c+1), 2)]:
                tiles.append((box - {missing}, color, 1))

    # Exact-cover search, preferring square tiles and then L pieces.
    by_cell = {p: [] for p in cells}
    for tile in tiles:
        shape, color, kind = tile
        if shape <= cells:
            for p in shape:
                by_cell[p].append(tile)

    def solve(left, chosen):
        if not left:
            return chosen
        p = min(left, key=lambda q: sum(t[0] <= left for t in by_cell[q]))
        options = sorted(by_cell[p], key=lambda t: t[2])
        for shape, color, kind in options:
            if shape <= left:
                result = solve(left - shape, chosen + [(shape, color)])
                if result is not None:
                    return result
        return None

    answer = solve(cells, [])
    if answer:
        for shape, color in answer:
            for r, c in shape:
                out[r][c] = color
    return out
