        for shape, color in sorted(by_cell[p], key=lambda item: -len(item[0])):
            if shape <= left:
                ans = search(left - shape, chosen + [(shape, color)])
                if ans is not None:
                    return ans
        return None

    solution = search(cells, [])
    if solution:
        for shape, color in solution:
            for r, c in shape:
